import{_ as t,o as s,c as o,ag as a}from"./chunks/framework.Ccn6roXv.js";const u=JSON.parse('{"title":"Publishing this site","description":"GitHub Pages, Actions, base URL, and alternatives.","frontmatter":{"title":"Publishing this site","description":"GitHub Pages, Actions, base URL, and alternatives."},"headers":[],"relativePath":"publishing.md","filePath":"publishing.md"}'),i={name:"publishing.md"};function n(r,e,d,p,l,c){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h2 id="platform-choice-free" tabindex="-1">Platform choice (free) <a class="header-anchor" href="#platform-choice-free" aria-label="Permalink to &quot;Platform choice (free)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Fits this project?</th></tr></thead><tbody><tr><td><strong>GitHub Pages</strong></td><td>Strong default — free on public repos, versioned beside your Markdown, CDN-backed. Works with Actions on every push to <code>main</code>.</td></tr><tr><td>Cloudflare Pages / Netlify</td><td>Also free tiers and Git-triggered builds; adds another dashboard. Prefer if you already use them.</td></tr><tr><td>Read the Docs</td><td>Great for Sphinx/MkDocs; less natural for VitePress.</td></tr></tbody></table><p>Recommendation: <strong><a href="https://pages.github.com/" target="_blank" rel="noreferrer">GitHub Pages</a></strong> + <strong><a href="https://vitepress.dev/" target="_blank" rel="noreferrer">VitePress</a></strong> + <strong>GitHub Actions</strong>. Include <strong>one</strong> <code>.github/workflows/publish-documentation.yml</code> layout that matches how you organize git.</p><h3 id="option-a-—-git-init-inside-this-folder-recommended-for-a-docs-only-repo" tabindex="-1">Option A — <code>git init</code> inside this folder (recommended for a docs-only repo) <a class="header-anchor" href="#option-a-—-git-init-inside-this-folder-recommended-for-a-docs-only-repo" aria-label="Permalink to &quot;Option A — \`git init\` inside this folder (recommended for a docs-only repo)&quot;">​</a></h3><p>The Git repository root is the VitePress project (this directory on disk):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;repo-root&gt;/</span></span>
<span class="line"><span>  .github/workflows/publish-documentation.yml</span></span>
<span class="line"><span>  .vitepress/</span></span>
<span class="line"><span>  guide/</span></span>
<span class="line"><span>  index.md</span></span>
<span class="line"><span>  package.json</span></span>
<span class="line"><span>  package-lock.json</span></span>
<span class="line"><span>  ...</span></span></code></pre></div><p>The workflow in this repo uses <code>npm ci</code> at the root and publishes <code>.vitepress/dist</code>.</p><h3 id="option-b-—-monorepo-docs-is-a-subdirectory" tabindex="-1">Option B — Monorepo (<code>docs/</code> is a subdirectory) <a class="header-anchor" href="#option-b-—-monorepo-docs-is-a-subdirectory" aria-label="Permalink to &quot;Option B — Monorepo (\`docs/\` is a subdirectory)&quot;">​</a></h3><p>Git root sits <strong>above</strong> the VitePress project:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;repo-root&gt;/</span></span>
<span class="line"><span>  docs/</span></span>
<span class="line"><span>    .vitepress/</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>  .github/workflows/publish-documentation.yml</span></span></code></pre></div><p>Configure the workflow with <code>working-directory: docs</code>, <code>cache-dependency-path: docs/package-lock.json</code>, and <code>publish_dir: docs/.vitepress/dist</code>.</p><p>VitePress gives you a TOC, local full-text search, dark mode, responsive layout, and side navigation without rewriting your existing <code>.md</code> files.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ol><li><p>Push the repo with the workflow and site files matching <strong>Option A</strong> or <strong>Option B</strong> above.</p></li><li><p>In GitHub: <strong>Settings → Pages → Build and deployment</strong>, set <strong>Deploy from a branch</strong>, branch <strong><code>gh-pages</code></strong>, folder <strong><code>/ (root)</code></strong>.</p></li><li><p>Grant Actions permission to deploy: <strong>Settings → Actions → General → Workflow permissions</strong> → allow read/write (default for <code>peaceiris/actions-gh-pages</code>).</p></li></ol><h2 id="local-preview" tabindex="-1">Local preview <a class="header-anchor" href="#local-preview" aria-label="Permalink to &quot;Local preview&quot;">​</a></h2><p>From this project root (same folder as <code>package.json</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Open the URL VitePress prints (usually <code>http://localhost:5173</code> plus your <code>base</code>).</p><h2 id="base-url-vitepress-base" tabindex="-1">Base URL (<code>VITEPRESS_BASE</code>) <a class="header-anchor" href="#base-url-vitepress-base" aria-label="Permalink to &quot;Base URL (\`VITEPRESS_BASE\`)&quot;">​</a></h2><p>VitePress needs a correct <strong>base</strong> path so assets resolve on GitHub Pages:</p><table tabindex="0"><thead><tr><th>Site type</th><th>Example URL</th><th><code>VITEPRESS_BASE</code></th></tr></thead><tbody><tr><td>Project site</td><td><code>https://user.github.io/my-repo/</code></td><td><code>/my-repo/</code></td></tr><tr><td>User/org site</td><td><code>https://user.github.io/</code> (repo <code>user.github.io</code>)</td><td><code>/</code></td></tr></tbody></table><p>The included workflow sets <code>VITEPRESS_BASE=/\${repo_name}/</code> from <code>GITHUB_REPOSITORY</code>. For a <strong>user pages</strong> repo, remove that step and set <code>VITEPRESS_BASE</code> to <code>/</code> (or leave unset and use <code>base: &#39;/&#39;</code> in config).</p><h2 id="custom-domain" tabindex="-1">Custom domain <a class="header-anchor" href="#custom-domain" aria-label="Permalink to &quot;Custom domain&quot;">​</a></h2><p>Add a <code>CNAME</code> file in <code>public/CNAME</code> at this project root (VitePress copies <code>public/</code> to dist). Point DNS per <a href="https://docs.github.com/en/pages/configuring-a-custom-domain-for-your-github-pages-site" target="_blank" rel="noreferrer">GitHub’s custom domain docs</a>.</p><h2 id="alternative-mkdocs-material" tabindex="-1">Alternative: MkDocs Material <a class="header-anchor" href="#alternative-mkdocs-material" aria-label="Permalink to &quot;Alternative: MkDocs Material&quot;">​</a></h2><p>If you prefer Python tooling, MkDocs Material is equally suitable for Markdown-only docs and publishes to gh-pages similarly. This folder is wired for VitePress intentionally (Node-only CI, aligns with TanStack tooling).</p>`,26)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
